import {
  HolographicCard,
  GlitchText,
} from '@/components/core/holographic-card';

export function HolographicCardBasic() {
  return (
    <div className='holographic-container flex h-[600px] w-full flex-col items-center justify-center'>
      <div className='holographic-grain-overlay' />
      <GlitchText
        text='CSS FUTURE'
        className='mb-8 text-4xl text-white md:text-6xl'
      />
      <HolographicCard
        title='Holographic Interface'
        description='Pure CSS art combining glitch typography, grain textures, floating holograms and 3D depth.'
        buttonText='EXPLORE'
        buttonHref='#'
      />
    </div>
  );
}

@reference "../../app/globals.css";

.holographic-container {
  --bg: #020617;
  --c1: #38bdf8;
  --c2: #a855f7;
  --c3: #22c55e;
  --noise: rgba(255, 255, 255, 0.05);
  position: relative;
  overflow: hidden;
}

/* background grain overlay localized to container */
.holographic-grain-overlay {
  position: absolute;
  inset: 0;
  background: repeating-radial-gradient(
    circle,
    var(--noise) 0 1px,
    transparent 1px 2px
  );
  mix-blend-mode: overlay;
  pointer-events: none;
  opacity: 0.35;
  animation: holographic-grain 0.25s steps(2) infinite;
}

@keyframes holographic-grain {
  to {
    transform: translate(2px, -2px);
  }
}

/* glitch title */
.holographic-glitch {
  position: relative;
  font-weight: 900;
  letter-spacing: 0.08em;
}
.holographic-glitch::before,
.holographic-glitch::after {
  content: attr(data-text);
  position: absolute;
  inset: 0;
  opacity: 0.8;
}
.holographic-glitch::before {
  color: var(--c1);
  transform: translate(3px, -2px);
  mix-blend-mode: screen;
  animation: holographic-glitch-anim 2s infinite alternate;
}
.holographic-glitch::after {
  color: var(--c2);
  transform: translate(-3px, 2px);
  mix-blend-mode: screen;
  animation: holographic-glitch-anim 1.5s infinite alternate-reverse;
}

@keyframes holographic-glitch-anim {
  0% {
    clip-path: inset(0 0 70% 0);
  }
  25% {
    clip-path: inset(20% 0 40% 0);
  }
  50% {
    clip-path: inset(40% 0 20% 0);
  }
  75% {
    clip-path: inset(10% 0 60% 0);
  }
  100% {
    clip-path: inset(0 0 0 0);
  }
}

/* holographic card */
.holographic-card-wrapper {
  perspective: 1000px;
}

.holographic-card {
  border-radius: 28px;
  background: linear-gradient(
    120deg,
    rgba(255, 255, 255, 0.08),
    rgba(255, 255, 255, 0.02)
  );
  backdrop-filter: blur(16px);
  box-shadow:
    0 0 50px rgba(56, 189, 248, 0.35),
    inset 0 0 35px rgba(255, 255, 255, 0.15);
  transform-style: preserve-3d;
  animation: holographic-float 6s ease-in-out infinite;
  position: relative;
}

.holographic-card::before {
  content: '';
  position: absolute;
  inset: -2px;
  border-radius: 30px;
  background: linear-gradient(
    120deg,
    transparent 20%,
    var(--c1),
    var(--c2),
    var(--c3),
    transparent 80%
  );
  filter: blur(25px);
  opacity: 0.4;
  z-index: -1;
  animation: holographic-holo 4s linear infinite;
  background-size: 400% 100%;
}

@keyframes holographic-holo {
  to {
    background-position: 400% 0;
  }
}

@keyframes holographic-float {
  0%,
  100% {
    transform: rotateX(12deg) rotateY(-10deg) translateY(0);
  }
  50% {
    transform: rotateX(18deg) rotateY(12deg) translateY(-25px);
  }
}

/* holographic button */
.holographic-btn {
  display: inline-block;
  border-radius: 999px;
  font-weight: 600;
  letter-spacing: 0.08em;
  color: white;
  text-decoration: none;
  background: linear-gradient(90deg, var(--c1), var(--c2), var(--c3));
  background-size: 300% 100%;
  animation: holographic-holo 3s linear infinite;
  box-shadow: 0 0 25px rgba(168, 85, 247, 0.6);
}

import * as React from 'react';
import { cn } from '@/lib/utils';
import './holographic-card.css';

export interface GlitchTextProps extends React.HTMLAttributes<HTMLHeadingElement> {
  text: string;
  as?: 'h1' | 'h2' | 'h3' | 'h4' | 'h5' | 'h6' | 'p' | 'span';
}

export const GlitchText = React.forwardRef<HTMLHeadingElement, GlitchTextProps>(
  ({ className, text, as: Comp = 'h1', ...props }, ref) => {
    return (
      <Comp
        ref={ref}
        className={cn('holographic-glitch', className)}
        data-text={text}
        {...props}
      >
        {text}
      </Comp>
    );
  }
);
GlitchText.displayName = 'GlitchText';

export interface HolographicCardProps extends React.HTMLAttributes<HTMLDivElement> {
  title?: React.ReactNode;
  description?: React.ReactNode;
  buttonText?: string;
  buttonHref?: string;
}

export const HolographicCard = React.forwardRef<
  HTMLDivElement,
  HolographicCardProps
>(
  (
    {
      className,
      title,
      description,
      buttonText,
      buttonHref,
      children,
      ...props
    },
    ref
  ) => {
    return (
      <div className='holographic-card-wrapper flex h-full w-full items-center justify-center p-8'>
        <div
          ref={ref}
          className={cn(
            'holographic-card w-full max-w-[420px] p-10 text-white',
            className
          )}
          {...props}
        >
          {title && <h2 className='mb-4 text-2xl font-bold'>{title}</h2>}

          {description && (
            <p className='leading-relaxed opacity-85'>{description}</p>
          )}

          {children}

          {buttonText && (
            <a
              href={buttonHref || '#'}
              className='holographic-btn mt-8 px-7 py-3 text-sm'
            >
              {buttonText}
            </a>
          )}
        </div>
      </div>
    );
  }
);
HolographicCard.displayName = 'HolographicCard';
